async def run(ctx, inputs):
    role=inputs["role"]
    guard=await ctx.call("tidb.query",{"sql":"SELECT s.id,s.institution_settlement_no,s.comments,s.currency,s.total_amount,r.id AS task_id,r.org_code,r.status,r.business_type FROM ri_settlement s JOIN ri_settlement_reinsurer r ON r.settlement_no=s.settlement_no AND r.is_deleted='N' WHERE s.id=%s AND s.settlement_no=%s AND s.from_org_code='000050' AND s.to_org_code='000053' AND s.is_deleted='N' ORDER BY r.business_type","params":[inputs["settlement_id"],inputs["settlement_no"]],"max_rows":3,"title":"保存默认汇率前双任务守卫"})
    if guard["truncated"] or guard["row_count"]!=2 or [(r["task_id"],r["org_code"],str(r["status"])) for r in guard["rows"]]!=[(inputs["from_task_id"],"000050","0"),(inputs["to_task_id"],"000053","0")]:raise ValueError("本轮结算任务状态变化，停止保存")
    if any(r["institution_settlement_no"]!=inputs["run_label"] or r["comments"]!="仅供本地自测 "+inputs["run_label"] or r["currency"]!="SETTLE-CNY" or str(r["total_amount"])!=inputs["expected_amount"] for r in guard["rows"]):raise ValueError("结算归属或金额变化")
    await ctx.call("playwright.page_assert_value",{"selector":"#settlementNo","value":inputs["settlement_no"],"role":role})
    await ctx.call("playwright.page_assert_value",{"selector":"#institutionSettlementNo","value":inputs["run_label"],"role":role})
    await ctx.call("playwright.page_click",{"selector":{"kind":"role","value":"button","name":"保 存","exact":True},"role":role})
    await ctx.call("playwright.page_assert_text",{"selector":"body","text":"操作成功","role":role})
    await ctx.call("playwright.page_open",{"url":"http://localhost:9877/SettlementManagement/BillSettlement/edit?taskId="+str(inputs["from_task_id"]),"role":role})
    await ctx.call("playwright.page_assert_value",{"selector":"#settlementNo","value":inputs["settlement_no"],"role":role})
    await ctx.call("playwright.page_assert_value",{"selector":"#institutionSettlementNo","value":inputs["run_label"],"role":role})
    await ctx.call("playwright.page_assert_value",{"selector":"#comments","value":"仅供本地自测 "+inputs["run_label"],"role":role})
    amount=await ctx.call("playwright.page_input_value",{"selector":"#totalAmount","role":role})
    if amount["value"].replace(",","")!=inputs["expected_amount"]:raise ValueError("重新打开后金额变化")
    await ctx.call("playwright.page_click",{"selector":{"kind":"role","value":"link","name":"结算单明细信息","exact":True},"role":role})
    await ctx.call("playwright.page_assert_text",{"selector":"#part-2","text":inputs["platform_statement_no"],"role":role})
    saved=await ctx.call("tidb.query",{"sql":"SELECT s.id,s.total_amount,s.payer_org_code,s.receiver_org_code,d.id AS detail_id,d.statement_id,d.statement_normal_id,d.platform_statement_no,d.platform_statement_no_temp,d.statement_currency,d.statement_amount,d.settlement_amount,d.settlement_currency_exchange_rate,d.statement_currency_exchange_rate,d.sign_chain_id,d.file_id FROM ri_settlement s JOIN ri_settlement_statement d ON d.settlement_no=s.settlement_no AND d.is_deleted='N' WHERE s.id=%s AND s.is_deleted='N'","params":[inputs["settlement_id"]],"max_rows":3,"title":"保存重新打开后的金额汇率与明细"})
    if saved["truncated"] or saved["row_count"]!=1:raise ValueError("结算明细不唯一")
    r=saved["rows"][0]
    if (r["platform_statement_no"] or r["platform_statement_no_temp"])!=inputs["platform_statement_no"] or str(r["statement_normal_id"])!=str(inputs["normal_id"]) or r["statement_id"]!=inputs["normal_id"] or r["statement_currency"]!="CNY" or any(str(r[k])!=inputs["expected_amount"] for k in ["total_amount","statement_amount","settlement_amount"]) or any(float(r[k])!=100 for k in ["settlement_currency_exchange_rate","statement_currency_exchange_rate"]) or r["payer_org_code"]!="000050" or r["receiver_org_code"]!="000053" or r["sign_chain_id"]!="owned-local-mock-sign-bill-257312" or r["file_id"]!="owned-local-pdf-ddfdea6f235bacf52923b856cda024c9e5b15fc8f5cb397135a109e522b3e662":raise ValueError("结算明细、金额汇率或文件引用变化")
    states=await ctx.call("tidb.query",{"sql":"SELECT id,org_code,status,business_type FROM ri_settlement_reinsurer WHERE settlement_no=%s AND is_deleted='N' ORDER BY business_type","params":[inputs["settlement_no"]],"max_rows":3,"title":"草稿保存后双方仍未提交"})
    if states["truncated"] or [(r["id"],r["org_code"],str(r["status"])) for r in states["rows"]]!=[(inputs["from_task_id"],"000050","0"),(inputs["to_task_id"],"000053","0")]:raise ValueError("保存后双方状态非草稿")
    return ctx.result(data={"settlement_id":inputs["settlement_id"],"settlement_no":inputs["settlement_no"],"from_task_id":inputs["from_task_id"],"to_task_id":inputs["to_task_id"],"normal_id":inputs["normal_id"],"run_label":inputs["run_label"],"saved":r,"role_states":states["rows"],"reopened":True,"submitted":False})
